/**
 * Dispute evidence PDF (D2-3). A4 portrait, 12pt body text, black and grey
 * only (dispute forms ask for no colour highlighting), every timestamp with
 * date, time and UTC offset in the store's time zone, and a "Generated by
 * Hay.chat" footer with page numbers on every page.
 *
 * Images arrive already prepared (JPEG, downscaled) or marked as left out;
 * the 4 MB cap is the caller's loop (see dispute-evidence.service).
 */
import PDFDocument from "pdfkit";
import type { MessageAttachment } from "@server/database/entities/message.entity";
import { formatZonedDateTime } from "@server/utils/zoned-datetime";
import { evidenceCopy, fillCopy, type EvidenceLocale, type EvidenceTemplate } from "./copy";
import type { EvidenceTimeline, TimelineEntry } from "./timeline";

export type PreparedImage = { kind: "image"; buffer: Buffer } | { kind: "omitted" | "unavailable" };

export interface EvidenceDocument {
  locale: EvidenceLocale;
  timeZone: string;
  generatedAt: Date;
  template: EvidenceTemplate;
  storeName: string;
  order: {
    label: string;
    platform: string | null;
    total: string | null;
    placedAt: string | null;
  } | null;
  customer: { name: string | null; email: string | null; phone: string | null } | null;
  conversations: Array<{ id: string; channel: string; created_at: Date }>;
  timeline: EvidenceTimeline;
  /** Policy text by document id (already trimmed to an excerpt). */
  policyExcerpts: Map<string, string>;
  /** Prepared image by attachment id; images not in the map are treated as unavailable. */
  images: Map<string, PreparedImage>;
}

const MARGIN = 56;
const BODY = 12;
const SMALL = 10;
const GREY = "#444444";
const POLICY_EXCERPT_CHARS = 1500;
const IMAGE_MAX = { width: 260, height: 260 };

// Characters the PDF standard fonts (WinAnsi) can draw beyond Latin-1.
const WIN_ANSI_EXTRA = "€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ";

/**
 * Text the built-in Helvetica can draw. Emoji and joiners are dropped; any
 * other character outside WinAnsi becomes "?" so it is visibly not reproduced.
 */
export function pdfSafe(text: string): string {
  return text
    .normalize("NFC")
    .replace(/\p{Extended_Pictographic}|[‍︎️]|\p{Emoji_Modifier}/gu, "")
    .replace(/[^\n\t -~ -ÿ]/g, (char) => (WIN_ANSI_EXTRA.includes(char) ? char : "?"));
}

export function channelLabel(channel: string, locale: EvidenceLocale): string {
  if (channel === "web" || channel === "webchat") return evidenceCopy(locale).webChannel;
  return channel ? channel.charAt(0).toUpperCase() + channel.slice(1) : channel;
}

export function isImageAttachment(attachment: MessageAttachment): boolean {
  return typeof attachment.type === "string" && attachment.type.startsWith("image/");
}

export function renderEvidencePdf(model: EvidenceDocument): Promise<Buffer> {
  const copy = evidenceCopy(model.locale);
  const at = (date: Date | string | null | undefined) => formatZonedDateTime(date, model.timeZone);
  const doc = new PDFDocument({
    size: "A4",
    margin: MARGIN,
    bufferPages: true,
    info: { Title: copy.title, Creator: "Hay.chat", Producer: "Hay.chat" },
  });
  const chunks: Buffer[] = [];
  const done = new Promise<Buffer>((resolve, reject) => {
    doc.on("data", (chunk: Buffer) => chunks.push(chunk));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
  });
  const width = doc.page.width - MARGIN * 2;

  const text = (value: string, options: PDFKit.Mixins.TextOptions = {}) =>
    doc.text(pdfSafe(value), { width, ...options });
  const heading = (value: string) => {
    doc.moveDown(1);
    doc.font("Helvetica-Bold").fontSize(15).fillColor("black");
    text(value);
    doc.moveDown(0.4);
    doc.font("Helvetica").fontSize(BODY);
  };
  const field = (label: string, value: string | null | undefined) => {
    if (!value) return;
    doc.font("Helvetica-Bold").fontSize(BODY).fillColor("black");
    doc.text(pdfSafe(`${label}: `), { continued: true, width });
    doc.font("Helvetica").text(pdfSafe(value));
  };

  // --- Cover ---
  doc.font("Helvetica-Bold").fontSize(20).fillColor("black");
  text(copy.title);
  doc.moveDown(0.6);
  doc.font("Helvetica").fontSize(BODY);
  field(copy.cover.store, model.storeName);
  if (model.template !== "generic") field(copy.cover.reason, copy.templates[model.template]);
  if (model.order) {
    field(copy.cover.order, model.order.label);
    field(copy.cover.platform, model.order.platform);
    field(copy.cover.orderTotal, model.order.total);
    field(copy.cover.orderPlaced, model.order.placedAt ? at(model.order.placedAt) : null);
  }
  if (model.customer) {
    const parts = [model.customer.name, model.customer.email, model.customer.phone].filter(Boolean);
    field(copy.cover.customer, parts.join(" | "));
  }
  field(copy.cover.conversations, String(model.conversations.length));
  const { period } = model.timeline;
  if (period) field(copy.cover.period, `${at(period.from)} - ${at(period.to)}`);
  field(copy.cover.generated, at(model.generatedAt));
  field(copy.cover.timeZone, model.timeZone);

  // --- Summary ---
  heading(copy.summaryHeading);
  const { counts } = model.timeline;
  if (period && counts.customerMessages + counts.replies > 0) {
    text(
      fillCopy(copy.summary, {
        conversations: model.conversations.length,
        store: model.storeName,
        channels: model.timeline.channels.map((c) => channelLabel(c, model.locale)).join(", "),
        from: at(period.from),
        to: at(period.to),
        customerMessages: counts.customerMessages,
        replies: counts.replies,
        actions: counts.actions,
      }),
    );
  } else {
    text(copy.summaryNoMessages);
  }

  // --- Key facts ---
  heading(copy.keyFactsHeading);
  if (model.timeline.keyFacts.length === 0) {
    text(copy.keyFactsNone);
  } else {
    for (const fact of model.timeline.keyFacts) {
      text(`- ${at(fact.at)}: ${fact.text}`, { indent: 0 });
      doc.moveDown(0.2);
    }
  }

  // --- Timeline ---
  heading(copy.timelineHeading);
  doc.fillColor(GREY).fontSize(SMALL);
  text(copy.timelineIntro);
  doc.fillColor("black").fontSize(BODY);
  const conversationsById = new Map(model.conversations.map((c) => [c.id, c]));
  let currentConversation: string | null = null;
  for (const entry of model.timeline.entries) {
    if (entry.conversationId !== currentConversation) {
      currentConversation = entry.conversationId;
      const conversation = conversationsById.get(entry.conversationId);
      if (conversation) {
        doc.moveDown(0.6);
        doc.font("Helvetica-Bold").fontSize(13);
        text(
          fillCopy(copy.conversationHeader, {
            channel: channelLabel(conversation.channel, model.locale),
            at: at(conversation.created_at),
          }),
        );
        doc.font("Helvetica").fontSize(BODY);
      }
    }
    renderEntry(entry);
  }

  // --- Policies ---
  if (model.timeline.policies.length > 0) {
    heading(copy.policiesHeading);
    doc.fillColor(GREY).fontSize(SMALL);
    text(copy.policiesIntro);
    doc.fillColor("black").fontSize(BODY);
    for (const policy of model.timeline.policies) {
      doc.moveDown(0.5);
      doc.font("Helvetica-Bold");
      text(policy.title);
      doc.font("Helvetica").fillColor(GREY).fontSize(SMALL);
      text(fillCopy(copy.policyFirstShown, { at: at(policy.firstUsedAt) }));
      doc.fillColor("black").fontSize(BODY);
      const excerpt = model.policyExcerpts.get(policy.documentId);
      if (excerpt) text(excerpt.slice(0, POLICY_EXCERPT_CHARS));
    }
  }

  // --- Footer on every page ---
  const range = doc.bufferedPageRange();
  for (let i = range.start; i < range.start + range.count; i++) {
    doc.switchToPage(i);
    const bottom = doc.page.margins.bottom;
    doc.page.margins.bottom = 0;
    doc.font("Helvetica").fontSize(SMALL).fillColor(GREY);
    doc.text(
      pdfSafe(
        fillCopy(copy.footer, {
          at: at(model.generatedAt),
          page: i + 1,
          pages: range.count,
        }),
      ),
      MARGIN,
      doc.page.height - MARGIN + 16,
      { width, align: "center", lineBreak: false },
    );
    doc.page.margins.bottom = bottom;
  }
  doc.end();
  return done;

  function renderEntry(entry: TimelineEntry) {
    doc.moveDown(0.5);
    if (entry.kind === "message") {
      doc.font("Helvetica-Bold").fontSize(BODY).fillColor("black");
      text(`${at(entry.at)} - ${copy.author[entry.author]}`);
      doc.font("Helvetica");
      if (entry.text.trim()) text(entry.text);
      if (entry.receipt) {
        doc.fillColor(GREY).fontSize(SMALL);
        text(
          fillCopy(copy.channelReceiptNote, {
            channel: channelLabel(entry.channel, model.locale),
            status: copy.receipt[entry.receipt],
          }),
        );
        doc.fillColor("black").fontSize(BODY);
      }
      for (const attachment of entry.attachments) renderAttachment(attachment);
      return;
    }
    doc.font("Helvetica-Oblique").fontSize(BODY).fillColor("black");
    text(`${at(entry.at)} - ${entry.text}`);
    doc.font("Helvetica");
  }

  function renderAttachment(attachment: MessageAttachment) {
    doc.fillColor(GREY).fontSize(SMALL);
    if (!isImageAttachment(attachment)) {
      text(fillCopy(copy.attachmentNotImage, { name: attachment.name }));
      doc.fillColor("black").fontSize(BODY);
      return;
    }
    const image = model.images.get(attachment.id);
    if (image?.kind === "image") {
      doc.moveDown(0.3);
      // Start the image on a new page when it would not fit on this one.
      if (doc.y + IMAGE_MAX.height > doc.page.height - doc.page.margins.bottom) doc.addPage();
      try {
        doc.image(image.buffer, MARGIN, doc.y, { fit: [IMAGE_MAX.width, IMAGE_MAX.height] });
        doc.moveDown(0.3);
        text(attachment.name);
      } catch {
        text(`${attachment.name}: ${copy.imageUnavailable}`);
      }
    } else {
      text(
        `${attachment.name}: ${image?.kind === "omitted" ? copy.imageOmitted : copy.imageUnavailable}`,
      );
    }
    doc.fillColor("black").fontSize(BODY);
  }
}
